INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('908d15f9-ae16-45d8-8bc8-d5d139bb6348', (SELECT id FROM categories WHERE slug = 'noi-chien-khong-dau' LIMIT 1), (SELECT id FROM brands WHERE slug = 'philips' LIMIT 1), 'SKU-PHIL-1001', '8931000001002', 'Nồi Chiên Không Dầu Điện Tử Philips Airfryer XXL HD9650 (7.3L - 2225W) (Bản Nâng Cấp Plus #1)', 'philips-n-i-chi-n-kh-ng-d-u-i-n-t-philips-airfryer-xxl-hd9-1002', 'Nồi Chiên Không Dầu Điện Tử Philips Airfryer XXL HD9650 (7.3L - 2225W) (Bản Nâng Cấp Plus #1) chính hãng Philips (Hà Lan). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Nồi Chiên Không Dầu Điện Tử Philips Airfryer XXL HD9650 (7.3L - 2225W) (Bản Nâng Cấp Plus #1)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Philips</strong> (Hà Lan).</p><p>Nồi chiên không dầu Philips XXL công nghệ Twin TurboStar loại bỏ đến 90% dầu mỡ thừa, dung tích siêu lớn chiên gà nguyên con giòn rụm bên ngoài mọng nước bên trong.</p><ul><li><strong>Dung tích:</strong> 7.3 Lít (chứa nguyên con gà 1.5kg)</li><li><strong>Công suất:</strong> 2225W</li><li><strong>Công nghệ chiên:</strong> Twin TurboStar giảm 90% lượng dầu mỡ</li><li><strong>Bảo hành:</strong> 24 tháng chính hãng</li></ul>', 5281200, 7117200, 26, 'https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=800', 'Hà Lan', 'Bảo hành chính hãng 12-24 tháng', 4.6, 67, 1579, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
