INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('56858f76-1c4d-4cee-9787-9d6dc90c41dc', (SELECT id FROM categories WHERE slug = 'robot-hut-bui' LIMIT 1), (SELECT id FROM brands WHERE slug = 'xiaomi' LIMIT 1), 'SKU-XIAO-1010', '8931000001011', 'Robot Hút Bụi Lau Nhà Xiaomi Vacuum X20 Plus (Lực hút 6000Pa - Tự giặt sấy giẻ) (Bản Nâng Cấp Plus #1)', 'xiaomi-robot-h-t-b-i-lau-nh-xiaomi-vacuum-x20-plus-l-c-h--1011', 'Robot Hút Bụi Lau Nhà Xiaomi Vacuum X20 Plus (Lực hút 6000Pa - Tự giặt sấy giẻ) (Bản Nâng Cấp Plus #1) chính hãng Xiaomi (Trung Quốc). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Robot Hút Bụi Lau Nhà Xiaomi Vacuum X20 Plus (Lực hút 6000Pa - Tự giặt sấy giẻ) (Bản Nâng Cấp Plus #1)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Xiaomi</strong> (Trung Quốc).</p><p>Xiaomi X20+ là dòng robot hút bụi lau nhà toàn năng với dock sạc đa năng tự giặt giẻ và gom rác thông minh, điều khiển tiện lợi qua Mi Home app.</p><ul><li><strong>Lực hút:</strong> 6000 Pa siêu mạnh</li><li><strong>Điều hướng:</strong> Laser LDS 360 độ + Cảm biến tránh vật cản</li><li><strong>Dock sạc tự động:</strong> Tự động giặt giẻ lau, sấy khô khí nóng, gom rác</li><li><strong>Bảo hành:</strong> 12 tháng chính hãng Xiaomi</li></ul>', 9709200, 12949200, 25, 'https://images.unsplash.com/photo-1518640467707-6811f4a6ab73?w=800', 'Trung Quốc', 'Bảo hành chính hãng 12-24 tháng', 4.9, 207, 778, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
