INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('ac424520-3d60-4999-a1b3-9a764efe4911', (SELECT id FROM categories WHERE slug = 'robot-hut-bui' LIMIT 1), (SELECT id FROM brands WHERE slug = 'panasonic' LIMIT 1), 'SKU-PANA-1012', '8931000001013', 'Máy Lọc Không Khí Bù Ẩm Panasonic Nanoe-X F-PXM55A (Phòng 42m2)', 'panasonic-m-y-l-c-kh-ng-kh-b-m-panasonic-nanoe-x-f-pxm55a-ph-1013', 'Máy Lọc Không Khí Bù Ẩm Panasonic Nanoe-X F-PXM55A (Phòng 42m2) chính hãng Panasonic (Nhật Bản). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Máy Lọc Không Khí Bù Ẩm Panasonic Nanoe-X F-PXM55A (Phòng 42m2)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Panasonic</strong> (Nhật Bản).</p><p>Máy lọc không khí Panasonic trang bị công nghệ Nanoe-X tiên tiến khử mùi hôi, lọc sạch 99.97% bụi mịn PM2.5 bảo vệ tối đa hệ hô hấp gia đình bạn.</p><ul><li><strong>Diệt khuẩn:</strong> Nanoe-X thế hệ mới ức chế 99.9% virus, vi khuẩn</li><li><strong>Bộ lọc:</strong> HEPA tổng hợp lọc bụi mịn PM2.5 + Than hoạt tính khử mùi</li><li><strong>Phạm vi sử dụng:</strong> Phù hợp phòng ngủ, phòng khách diện tích đến 42m2</li><li><strong>Bảo hành:</strong> 12 tháng Panasonic chính hãng</li></ul>', 6490000, 8200000, 21, 'https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=800', 'Nhật Bản', 'Bảo hành chính hãng 12-24 tháng', 4.7, 198, 489, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
