INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('68420a8d-5a24-4a9e-9e50-fb2dae97fe6a', (SELECT id FROM categories WHERE slug = 'robot-hut-bui' LIMIT 1), (SELECT id FROM brands WHERE slug = 'panasonic' LIMIT 1), 'SKU-PANA-1013', '8931000001014', 'Máy Lọc Không Khí Bù Ẩm Panasonic Nanoe-X F-PXM55A (Phòng 42m2) (Bản Nâng Cấp Plus #1)', 'panasonic-m-y-l-c-kh-ng-kh-b-m-panasonic-nanoe-x-f-pxm55a-ph-1014', 'Máy Lọc Không Khí Bù Ẩm Panasonic Nanoe-X F-PXM55A (Phòng 42m2) (Bản Nâng Cấp Plus #1) chính hãng Panasonic (Nhật Bản). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Máy Lọc Không Khí Bù Ẩm Panasonic Nanoe-X F-PXM55A (Phòng 42m2) (Bản Nâng Cấp Plus #1)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Panasonic</strong> (Nhật Bản).</p><p>Máy lọc không khí Panasonic trang bị công nghệ Nanoe-X tiên tiến khử mùi hôi, lọc sạch 99.97% bụi mịn PM2.5 bảo vệ tối đa hệ hô hấp gia đình bạn.</p><ul><li><strong>Diệt khuẩn:</strong> Nanoe-X thế hệ mới ức chế 99.9% virus, vi khuẩn</li><li><strong>Bộ lọc:</strong> HEPA tổng hợp lọc bụi mịn PM2.5 + Than hoạt tính khử mùi</li><li><strong>Phạm vi sử dụng:</strong> Phù hợp phòng ngủ, phòng khách diện tích đến 42m2</li><li><strong>Bảo hành:</strong> 12 tháng Panasonic chính hãng</li></ul>', 7009200, 8856000, 21, 'https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=800', 'Nhật Bản', 'Bảo hành chính hãng 12-24 tháng', 4.9, 94, 697, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
