INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('faf2ef47-2811-4367-8e2e-68c3f3328a76', (SELECT id FROM categories WHERE slug = 'ao-thun-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'coolmate' LIMIT 1), 'SKU-COOL-1021', '8931000001022', 'Áo Thun Nam Cotton Compact Siêu Thoáng Mát Coolmate Cổ Tròn Form Regular', 'coolmate--o-thun-nam-cotton-compact-si-u-tho-ng-m-t-coolmat-1022', 'Áo Thun Nam Cotton Compact Siêu Thoáng Mát Coolmate Cổ Tròn Form Regular chính hãng Coolmate (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Áo Thun Nam Cotton Compact Siêu Thoáng Mát Coolmate Cổ Tròn Form Regular</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Coolmate</strong> (Việt Nam).</p><p>Áo thun nam Coolmate may từ sợi Cotton Compact chải kỹ mềm mại, thấm hút mồ hôi tối ưu, không phai màu hay co rút sau nhiều lần giặt.</p><ul><li><strong>Chất vải:</strong> 100% Cotton Compact 220gsm chống xù lông</li><li><strong>Kiểu dáng:</strong> Regular Fit tôn dáng, năng động</li><li><strong>Sản xuất:</strong> Việt Nam (Tự hào sản xuất tại xưởng may đạt chuẩn)</li><li><strong>Đổi trả:</strong> 60 ngày đổi trả miễn phí không cần lý do</li></ul>', 189000, 259000, 27, 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.7, 221, 1326, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
