INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('390cfb0c-8f61-4997-b216-6ca279a8b027', (SELECT id FROM categories WHERE slug = 'ao-thun-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'coolmate' LIMIT 1), 'SKU-COOL-1022', '8931000001023', 'Áo Thun Nam Cotton Compact Siêu Thoáng Mát Coolmate Cổ Tròn Form Regular (Bản Nâng Cấp Plus #1)', 'coolmate--o-thun-nam-cotton-compact-si-u-tho-ng-m-t-coolmat-1023', 'Áo Thun Nam Cotton Compact Siêu Thoáng Mát Coolmate Cổ Tròn Form Regular (Bản Nâng Cấp Plus #1) chính hãng Coolmate (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Áo Thun Nam Cotton Compact Siêu Thoáng Mát Coolmate Cổ Tròn Form Regular (Bản Nâng Cấp Plus #1)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Coolmate</strong> (Việt Nam).</p><p>Áo thun nam Coolmate may từ sợi Cotton Compact chải kỹ mềm mại, thấm hút mồ hôi tối ưu, không phai màu hay co rút sau nhiều lần giặt.</p><ul><li><strong>Chất vải:</strong> 100% Cotton Compact 220gsm chống xù lông</li><li><strong>Kiểu dáng:</strong> Regular Fit tôn dáng, năng động</li><li><strong>Sản xuất:</strong> Việt Nam (Tự hào sản xuất tại xưởng may đạt chuẩn)</li><li><strong>Đổi trả:</strong> 60 ngày đổi trả miễn phí không cần lý do</li></ul>', 204120, 279720, 27, 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.8, 182, 354, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
