INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('bf586695-8f80-4b8c-93aa-d250edd15987', (SELECT id FROM categories WHERE slug = 'ao-thun-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'coolmate' LIMIT 1), 'SKU-COOL-1025', '8931000001026', 'Áo Polo Nam Pique Cotton Thoáng Khí Chống Nhăn Coolmate Cafe Dệt Tổ Ong (Bản Nâng Cấp Plus #1)', 'coolmate--o-polo-nam-pique-cotton-tho-ng-kh-ch-ng-nh-n-cool-1026', 'Áo Polo Nam Pique Cotton Thoáng Khí Chống Nhăn Coolmate Cafe Dệt Tổ Ong (Bản Nâng Cấp Plus #1) chính hãng Coolmate (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Áo Polo Nam Pique Cotton Thoáng Khí Chống Nhăn Coolmate Cafe Dệt Tổ Ong (Bản Nâng Cấp Plus #1)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Coolmate</strong> (Việt Nam).</p><p>Áo Polo Cafe Coolmate dệt từ sợi bã cà phê kiểm soát mùi vượt trội, giữ phom đứng dáng thanh lịch khi đi làm hay dạo phố.</p><ul><li><strong>Sợi vải:</strong> 50% Sợi bã cà phê S.Café + 50% Recycled Poly khử mùi</li><li><strong>Kiểu cổ:</strong> Cổ bẻ dệt bo định hình không bị quăn mép</li><li><strong>Tính năng:</strong> Kháng khuẩn tự nhiên, chống tia UV UPF 50+</li><li><strong>Đổi trả:</strong> 60 ngày đổi trả 100%</li></ul>', 322920, 430920, 25, 'https://images.unsplash.com/photo-1581655353564-df123a1eb820?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.8, 100, 1295, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
