INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('0c5accd3-95e1-4954-bec8-e004705a9b27', (SELECT id FROM categories WHERE slug = 'ao-thun-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'uniqlo' LIMIT 1), 'SKU-UNIQ-1027', '8931000001028', 'Áo Thun Nam Cổ Tròn Không Đường May Uniqlo AIRism Cotton Siêu Nhẹ', 'uniqlo--o-thun-nam-c-tr-n-kh-ng-ng-may-uniqlo-airism-cott-1028', 'Áo Thun Nam Cổ Tròn Không Đường May Uniqlo AIRism Cotton Siêu Nhẹ chính hãng Uniqlo (Nhật Bản). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Áo Thun Nam Cổ Tròn Không Đường May Uniqlo AIRism Cotton Siêu Nhẹ</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Uniqlo</strong> (Nhật Bản).</p><p>Áo thun Uniqlo AIRism Cotton kết hợp hoàn hảo giữa độ mát mịn của sợi AIRism và vẻ đẹp đứng phom của vải cotton tự nhiên.</p><ul><li><strong>Vải AIRism:</strong> Mặt trong sợi AIRism mát lạnh, mặt ngoài Cotton tự nhiên</li><li><strong>Kiểu dáng:</strong> Oversized hiện đại, tay lỡ trẻ trung</li><li><strong>Thương hiệu:</strong> Uniqlo Nhật Bản</li><li><strong>Giặt ủi:</strong> Giặt máy giặt chế độ nhẹ</li></ul>', 349000, 420000, 17, 'https://images.unsplash.com/photo-1523381210434-271e8be1f52b?w=800', 'Nhật Bản', 'Bảo hành chính hãng 12-24 tháng', 5.0, 96, 1356, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
