INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('b3fe3074-bdeb-44ba-9037-deb71f0393b4', (SELECT id FROM categories WHERE slug = 'ao-so-mi-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'an-phuoc' LIMIT 1), 'SKU-AN-P-1030', '8931000001031', 'Áo Sơ Mi Nam Tay Dài Cao Cấp An Phước Pierre Cardin Chống Nhăn Form Classic', 'an-phuoc--o-s-mi-nam-tay-d-i-cao-c-p-an-ph-c-pierre-cardin--1031', 'Áo Sơ Mi Nam Tay Dài Cao Cấp An Phước Pierre Cardin Chống Nhăn Form Classic chính hãng An Phước (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Áo Sơ Mi Nam Tay Dài Cao Cấp An Phước Pierre Cardin Chống Nhăn Form Classic</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>An Phước</strong> (Việt Nam).</p><p>Áo sơ mi nam An Phước Pierre Cardin thể hiện đẳng cấp quý ông công sở, chất vải 100% cotton chống nhăn cao cấp giữ phom phẳng phiu suốt ngày dài.</p><ul><li><strong>Vải chính:</strong> 100% Cotton chải kỹ xử lý công nghệ Non-Iron chống nhăn</li><li><strong>Chi tiết:</strong> Cúc áo khắc laser xà cừ, đường may 20 mũi/inch</li><li><strong>Form áo:</strong> Regular Fit công sở sang trọng</li><li><strong>Chính hãng:</strong> Cam kết chính hãng An Phước Pierre Cardin</li></ul>', 990000, 1350000, 27, 'https://images.unsplash.com/photo-1594938298603-c8148c4dae35?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.9, 73, 1157, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
