INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('0d2b2bfb-d891-444b-9d26-00c40439945a', (SELECT id FROM categories WHERE slug = 'quan-jeans-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'routine' LIMIT 1), 'SKU-ROUT-1036', '8931000001037', 'Quần Jeans Nam Xanh Indigo Routine Dáng Slim Fit Co Giãn 4 Chiều', 'routine-qu-n-jeans-nam-xanh-indigo-routine-d-ng-slim-fit-c-1037', 'Quần Jeans Nam Xanh Indigo Routine Dáng Slim Fit Co Giãn 4 Chiều chính hãng Routine (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Quần Jeans Nam Xanh Indigo Routine Dáng Slim Fit Co Giãn 4 Chiều</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Routine</strong> (Việt Nam).</p><p>Quần Jeans nam Routine với form Slim Fit tôn dáng đôi chân, chất vải co giãn nhẹ đem lại sự thoải mái khi di chuyển cả ngày.</p><ul><li><strong>Vải Denim:</strong> 98% Cotton Denim + 2% Spandex co giãn đàn hồi</li><li><strong>Wash màu:</strong> Kỹ thuật Enzyme Wash bền màu, giữ độ sờn tự nhiên</li><li><strong>Khóa kéo:</strong> Khóa đồng YKK chính hãng siêu bền</li><li><strong>Đổi trả:</strong> Hỗ trợ đổi size trong 30 ngày</li></ul>', 590000, 790000, 25, 'https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.8, 51, 217, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
