INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('f13f820e-e614-4216-940a-bd16e553f1ce', (SELECT id FROM categories WHERE slug = 'quan-jeans-nam' LIMIT 1), (SELECT id FROM brands WHERE slug = 'routine' LIMIT 1), 'SKU-ROUT-1038', '8931000001039', 'Quần Jeans Nam Xanh Indigo Routine Dáng Slim Fit Co Giãn 4 Chiều (Bản Nâng Cấp Plus #2)', 'routine-qu-n-jeans-nam-xanh-indigo-routine-d-ng-slim-fit-c-1039', 'Quần Jeans Nam Xanh Indigo Routine Dáng Slim Fit Co Giãn 4 Chiều (Bản Nâng Cấp Plus #2) chính hãng Routine (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Quần Jeans Nam Xanh Indigo Routine Dáng Slim Fit Co Giãn 4 Chiều (Bản Nâng Cấp Plus #2)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Routine</strong> (Việt Nam).</p><p>Quần Jeans nam Routine với form Slim Fit tôn dáng đôi chân, chất vải co giãn nhẹ đem lại sự thoải mái khi di chuyển cả ngày.</p><ul><li><strong>Vải Denim:</strong> 98% Cotton Denim + 2% Spandex co giãn đàn hồi</li><li><strong>Wash màu:</strong> Kỹ thuật Enzyme Wash bền màu, giữ độ sờn tự nhiên</li><li><strong>Khóa kéo:</strong> Khóa đồng YKK chính hãng siêu bền</li><li><strong>Đổi trả:</strong> Hỗ trợ đổi size trong 30 ngày</li></ul>', 684400, 916399, 25, 'https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.8, 70, 1341, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
