INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('4ccbd2e2-048d-4c85-901b-c55494d3b82f', (SELECT id FROM categories WHERE slug = 'vay-dam-nu' LIMIT 1), (SELECT id FROM brands WHERE slug = 'elise' LIMIT 1), 'SKU-ELIS-1039', '8931000001040', 'Đầm Xòe Công Sở Nữ Elise Cổ Chữ V Thắt Đai Eo Tôn Dáng Cao Cấp', 'elise--m-x-e-c-ng-s-n-elise-c-ch-v-th-t-ai-eo-t-n-d-ng-c-1040', 'Đầm Xòe Công Sở Nữ Elise Cổ Chữ V Thắt Đai Eo Tôn Dáng Cao Cấp chính hãng Elise (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Đầm Xòe Công Sở Nữ Elise Cổ Chữ V Thắt Đai Eo Tôn Dáng Cao Cấp</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Elise</strong> (Việt Nam).</p><p>Thiết kế đầm xòe Elise nổi bật với đường cắt may chuẩn xác, ôm nhẹ vòng eo và xòe nhẹ che khuyết điểm, toát lên nét đẹp thanh lịch quý phái.</p><ul><li><strong>Chất vải:</strong> Tuyết Mưa Hàn Quốc cao cấp co giãn nhẹ</li><li><strong>Kiểu dáng:</strong> Đầm chữ A xòe nhẹ, đai eo phối khóa kim loại sang trọng</li><li><strong>Lớp lót:</strong> Lót lụa Habutai mềm mịn thấm hút</li><li><strong>Chính hãng:</strong> 100% Elise Fashion chính hãng</li></ul>', 1498000, 1998000, 25, 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.9, 295, 715, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
