INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('994a0305-a0f2-429a-950f-127a286ac6c3', (SELECT id FROM categories WHERE slug = 'ao-blazer-nu' LIMIT 1), (SELECT id FROM brands WHERE slug = 'zara' LIMIT 1), 'SKU-ZARA-1049', '8931000001050', 'Áo Khoác Blazer Nữ 2 Hàng Khuy Zara Oversized Phong Cách Hàn Quốc (Bản Nâng Cấp Plus #1)', 'zara--o-kho-c-blazer-n-2-h-ng-khuy-zara-oversized-phong-1050', 'Áo Khoác Blazer Nữ 2 Hàng Khuy Zara Oversized Phong Cách Hàn Quốc (Bản Nâng Cấp Plus #1) chính hãng Zara (Tây Ban Nha). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Áo Khoác Blazer Nữ 2 Hàng Khuy Zara Oversized Phong Cách Hàn Quốc (Bản Nâng Cấp Plus #1)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Zara</strong> (Tây Ban Nha).</p><p>Áo Blazer Zara 2 hàng khuy là item không thể thiếu trong tủ đồ của các cô gái hiện đại, dễ dàng phối cùng áo phông, croptop hoặc đầm liền.</p><ul><li><strong>Vải chính:</strong> Vải Dạ dệt chéo đứng phom, giữ ấm nhẹ</li><li><strong>Cúc áo:</strong> Khuy kim loại mạ đồng vintage, độn vai tinh tế</li><li><strong>Form áo:</strong> Oversized chuẩn xu hướng street style</li><li><strong>Thương hiệu:</strong> Zara Tây Ban Nha</li></ul>', 1402920, 1942920, 28, 'https://images.unsplash.com/photo-1483985988355-763728e1935b?w=800', 'Tây Ban Nha', 'Bảo hành chính hãng 12-24 tháng', 4.7, 102, 970, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
