INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('6b4ffe76-0d9e-4fe9-b26c-065ef7ad5367', (SELECT id FROM categories WHERE slug = 'kem-chong-nang' LIMIT 1), (SELECT id FROM brands WHERE slug = 'la-roche-posay' LIMIT 1), 'SKU-LA-R-1051', '8931000001052', 'Kem Chống Nắng La Roche-Posay Anthelios UVMune 400 Oil Control Gel-Cream SPF50+ (50ml)', 'la-roche-posay-kem-ch-ng-n-ng-la-roche-posay-anthelios-uvmune-400-1052', 'Kem Chống Nắng La Roche-Posay Anthelios UVMune 400 Oil Control Gel-Cream SPF50+ (50ml) chính hãng La Roche-Posay (Pháp). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Kem Chống Nắng La Roche-Posay Anthelios UVMune 400 Oil Control Gel-Cream SPF50+ (50ml)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>La Roche-Posay</strong> (Pháp).</p><p>Kem chống nắng kiểm soát dầu số 1 từ Pháp với màng lọc Mexoryl 400 ngăn chặn cả tia UVA siêu dài, kết cấu mỏng nhẹ thẩm thấu nhanh không gây bết dính.</p><ul><li><strong>SPF/PA:</strong> SPF50+ / PA++++ với màng lọc Mexoryl 400 độc quyền</li><li><strong>Phù hợp da:</strong> Da dầu, hỗn hợp thiên dầu, da mụn nhạy cảm</li><li><strong>Kiểm soát dầu:</strong> Airlicium hấp thụ bã nhờn, kiềm dầu đến 12h</li><li><strong>Cam kết:</strong> Chính hãng 100% tem phụ nhập khẩu chính ngạch</li></ul>', 435000, 535000, 19, 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=800', 'Pháp', 'Bảo hành chính hãng 12-24 tháng', 4.8, 104, 1530, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
