INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('e3bd50c0-3a0f-4b7c-a7f9-3b41063646dd', (SELECT id FROM categories WHERE slug = 'serum-tinh-chat' LIMIT 1), (SELECT id FROM brands WHERE slug = 'paulas-choice' LIMIT 1), 'SKU-PAUL-1057', '8931000001058', 'Dung Dịch Tẩy Tế Bào Chết Hóa Học Paula''s Choice Skin Perfecting 2% BHA Liquid Exfoliant (118ml)', 'paulas-choice-dung-d-ch-t-y-t-b-o-ch-t-h-a-h-c-paula-s-choice-sk-1058', 'Dung Dịch Tẩy Tế Bào Chết Hóa Học Paula''s Choice Skin Perfecting 2% BHA Liquid Exfoliant (118ml) chính hãng Paula''s Choice (Mỹ). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Dung Dịch Tẩy Tế Bào Chết Hóa Học Paula''s Choice Skin Perfecting 2% BHA Liquid Exfoliant (118ml)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Paula''s Choice</strong> (Mỹ).</p><p>Sản phẩm tẩy tế bào chết hóa học huyền thoại chứa 2% BHA hòa tan dầu thừa sâu trong lỗ chân lông, giải quyết dứt điểm mụn đầu đen và mụn ẩn.</p><ul><li><strong>Salicylic Acid:</strong> 2% BHA làm sạch sâu lỗ chân lông, giảm mụn ẩn</li><li><strong>Chỉ số pH:</strong> 3.2 - 3.8 tối ưu hiệu quả tẩy da chết dịu nhẹ</li><li><strong>Dung tích:</strong> 118ml</li><li><strong>Nguồn gốc:</strong> Paula''s Choice USA chính hãng</li></ul>', 899000, 1100000, 18, 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=800', 'Mỹ', 'Bảo hành chính hãng 12-24 tháng', 4.9, 110, 529, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
