INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('a4092544-dff2-402f-861f-19b64c7d6443', (SELECT id FROM categories WHERE slug = 'serum-tinh-chat' LIMIT 1), (SELECT id FROM brands WHERE slug = 'cocoon' LIMIT 1), 'SKU-COCO-1060', '8931000001061', 'Nước Dưỡng Tóc Tinh Dầu Bưởi Thuần Chay Cocoon Pomelo Hair Tonic Giảm Rụng Tóc (140ml)', 'cocoon-n-c-d-ng-t-c-tinh-d-u-b-i-thu-n-chay-cocoon-pomelo-1061', 'Nước Dưỡng Tóc Tinh Dầu Bưởi Thuần Chay Cocoon Pomelo Hair Tonic Giảm Rụng Tóc (140ml) chính hãng Cocoon (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Nước Dưỡng Tóc Tinh Dầu Bưởi Thuần Chay Cocoon Pomelo Hair Tonic Giảm Rụng Tóc (140ml)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Cocoon</strong> (Việt Nam).</p><p>Nước dưỡng tóc Cocoon từ tinh dầu vỏ bưởi Việt Nam cung cấp dưỡng chất thiết yếu cho da đầu, giảm gãy rụng và nuôi tóc con mọc dày bồng bềnh.</p><ul><li><strong>Nguyên liệu:</strong> Tinh dầu vỏ bưởi nguyên chất + Vitamin B5 + Xylishine</li><li><strong>Tiêu chuẩn:</strong> 100% Thuần chay (Vegan) chứng nhận bởi The Vegan Society</li><li><strong>Hiệu quả:</strong> Kích thích mọc tóc nhanh, nuôi dưỡng nang tóc chắc khỏe</li><li><strong>Thương hiệu:</strong> Cocoon Vietnam</li></ul>', 145000, 185000, 22, 'https://images.unsplash.com/photo-1571781926291-c477ebfd024b?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.8, 310, 199, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
