INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('e7aa4218-6a0d-4836-970e-7ad82bf753b1', (SELECT id FROM categories WHERE slug = 'chan-ga-goi-dem' LIMIT 1), (SELECT id FROM brands WHERE slug = 'ikea' LIMIT 1), 'SKU-IKEA-1066', '8931000001067', 'Bộ Drap Chăn Ga Gối Cotton Lụa Cao Cấp IKEA ÄNGSLILJA (1m8 x 2m)', 'ikea-b-drap-ch-n-ga-g-i-cotton-l-a-cao-c-p-ikea-ngslilj-1067', 'Bộ Drap Chăn Ga Gối Cotton Lụa Cao Cấp IKEA ÄNGSLILJA (1m8 x 2m) chính hãng IKEA (Thụy Điển). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Bộ Drap Chăn Ga Gối Cotton Lụa Cao Cấp IKEA ÄNGSLILJA (1m8 x 2m)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>IKEA</strong> (Thụy Điển).</p><p>Bộ chăn ga IKEA chất liệu cotton lụa thoáng khí cao cấp mang lại giấc ngủ êm ái, nâng niu làn da sau những giờ làm việc mệt mỏi.</p><ul><li><strong>Sợi dệt:</strong> 100% Sợi bông Cotton hữu cơ mật độ 300 sợi/inch</li><li><strong>Quy cách:</strong> 1 Ga bọc chun (180x200cm) + 1 Vỏ chăn (200x220cm) + 2 Vỏ gối</li><li><strong>Đặc điểm:</strong> Mát mẻ mùa hè, giữ nhiệt ấm êm mùa đông, không xù lông</li><li><strong>Xuất xứ:</strong> IKEA Thụy Điển</li></ul>', 1250000, 1650000, 24, 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=800', 'Thụy Điển', 'Bảo hành chính hãng 12-24 tháng', 4.6, 285, 585, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
