INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('62ac4fba-edf0-4ad5-b883-9c88df694cd4', (SELECT id FROM categories WHERE slug = 'dung-cu-nha-bep' LIMIT 1), (SELECT id FROM brands WHERE slug = 'lock-lock' LIMIT 1), 'SKU-LOCK-1069', '8931000001070', 'Bộ 3 Hộp Thủy Tinh Chịu Nhiệt Lock&Lock Borosilicate Glass Kèm Túi Giữ Nhiệt', 'lock-lock-b-3-h-p-th-y-tinh-ch-u-nhi-t-lock-lock-borosilicat-1070', 'Bộ 3 Hộp Thủy Tinh Chịu Nhiệt Lock&Lock Borosilicate Glass Kèm Túi Giữ Nhiệt chính hãng Lock&Lock (Hàn Quốc). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Bộ 3 Hộp Thủy Tinh Chịu Nhiệt Lock&Lock Borosilicate Glass Kèm Túi Giữ Nhiệt</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Lock&Lock</strong> (Hàn Quốc).</p><p>Bộ hộp thủy tinh Lock&Lock chịu nhiệt cao cấp thích hợp đựng cơm mang đi làm, giữ nhiệt tốt và không bám mùi màu thực phẩm.</p><ul><li><strong>Thủy tinh:</strong> Thủy tinh Borosilicate chịu nhiệt đến 400°C</li><li><strong>Tiện ích:</strong> An toàn với lò vi sóng, lò nướng, máy rửa chén</li><li><strong>Gioăng cao su:</strong> Nắp khóa 4 khớp kín khí tuyệt đối chống tràn nước</li><li><strong>Thương hiệu:</strong> Lock&Lock chính hãng</li></ul>', 380000, 520000, 27, 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=800', 'Hàn Quốc', 'Bảo hành chính hãng 12-24 tháng', 4.9, 282, 1720, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
