INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('08a5f02a-a329-45d2-bf18-006e1f6bc678', (SELECT id FROM categories WHERE slug = 'dung-cu-nha-bep' LIMIT 1), (SELECT id FROM brands WHERE slug = 'inochi' LIMIT 1), 'SKU-INOC-1072', '8931000001073', 'Bộ Thau Rổ Xoay Đa Năng Cao Cấp Inochi Yoko Kháng Khuẩn Ag+', 'inochi-b-thau-r-xoay-a-n-ng-cao-c-p-inochi-yoko-kh-ng-khu-1073', 'Bộ Thau Rổ Xoay Đa Năng Cao Cấp Inochi Yoko Kháng Khuẩn Ag+ chính hãng Inochi (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Bộ Thau Rổ Xoay Đa Năng Cao Cấp Inochi Yoko Kháng Khuẩn Ag+</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Inochi</strong> (Việt Nam).</p><p>Bộ rổ xoay Inochi Yoko tiện lợi với thiết kế thông minh tự cân bằng giúp rửa rau củ, trái cây ráo nước nhanh chóng và vệ sinh.</p><ul><li><strong>Nhựa nguyên sinh:</strong> Nhựa PP nguyên sinh cao cấp tích hợp ion Bạc Ag+ kháng khuẩn</li><li><strong>Trục xoay:</strong> Trục xoay 360 độ tự cân bằng, thoát nước siêu nhanh</li><li><strong>Đường kính:</strong> 26cm</li><li><strong>Xuất xứ:</strong> Inochi Việt Nam</li></ul>', 185000, 245000, 24, 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.8, 270, 1556, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
