INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('0f4b7d7a-9145-4bc9-a210-e167ed119bac', (SELECT id FROM categories WHERE slug = 'den-trang-tri' LIMIT 1), (SELECT id FROM brands WHERE slug = 'rang-dong' LIMIT 1), 'SKU-RANG-1075', '8931000001076', 'Đèn Bàn Học LED Chống Cận Thị Rạng Đông Cảm Ứng Đổi 3 Màu Ánh Sáng RL-36 (9W)', 'rang-dong--n-b-n-h-c-led-ch-ng-c-n-th-r-ng-ng-c-m-ng-i-3-m-u-1076', 'Đèn Bàn Học LED Chống Cận Thị Rạng Đông Cảm Ứng Đổi 3 Màu Ánh Sáng RL-36 (9W) chính hãng Rạng Đông (Việt Nam). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Đèn Bàn Học LED Chống Cận Thị Rạng Đông Cảm Ứng Đổi 3 Màu Ánh Sáng RL-36 (9W)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>Rạng Đông</strong> (Việt Nam).</p><p>Đèn LED để bàn Rạng Đông trang bị chip LED chất lượng cao không phát ra tia tử ngoại, bảo vệ tối đa thị lực học sinh và dân văn phòng.</p><ul><li><strong>CRI:</strong> CRI > 90 phản ánh trung thực màu sắc, không gây mỏi mắt</li><li><strong>Nhiệt độ màu:</strong> 3 màu (Trắng 6500K, Trung tính 4000K, Vàng ấm 3000K)</li><li><strong>Điện năng:</strong> 9W tiết kiệm điện</li><li><strong>Chính hãng:</strong> Bảo hành 24 tháng Rạng Đông</li></ul>', 320000, 450000, 29, 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=800', 'Việt Nam', 'Bảo hành chính hãng 12-24 tháng', 4.9, 219, 978, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
