INSERT INTO products (id, category_id, brand_id, sku, barcode, name, slug, short_description, description, price, original_price, discount_percent, image_url, origin_country, warranty_policy, rating_avg, rating_count, sold_count, status, version, created_at, updated_at) VALUES ('8cf84f18-1328-4736-b54a-f3f775247dd0', (SELECT id FROM categories WHERE slug = 'ke-tu-gia-do' LIMIT 1), (SELECT id FROM brands WHERE slug = 'ikea' LIMIT 1), 'SKU-IKEA-1078', '8931000001079', 'Xe Đẩy Kệ Để Đồ Đa Năng 3 Tầng IKEA RÅSKOG Bằng Thép Sơn Tĩnh Điện (Có Bánh Xe)', 'ikea-xe-y-k-a-n-ng-3-t-ng-ikea-r-skog-b-ng-th-p-s-n-t-n-1079', 'Xe Đẩy Kệ Để Đồ Đa Năng 3 Tầng IKEA RÅSKOG Bằng Thép Sơn Tĩnh Điện (Có Bánh Xe) chính hãng IKEA (Thụy Điển). Chất lượng vượt trội, thiết kế tinh tế.', '<p><strong>Xe Đẩy Kệ Để Đồ Đa Năng 3 Tầng IKEA RÅSKOG Bằng Thép Sơn Tĩnh Điện (Có Bánh Xe)</strong> là sản phẩm cao cấp chính hãng từ thương hiệu <strong>IKEA</strong> (Thụy Điển).</p><p>Kệ xe đẩy 3 tầng IKEA RÅSKOG tiện dụng trong mọi không gian bếp, phòng tắm hoặc bàn làm việc, dễ dàng di chuyển và vệ sinh.</p><ul><li><strong>Khung xe:</strong> Thép phủ sơn tĩnh điện chống gỉ sét, chịu tải 30kg</li><li><strong>Di chuyển:</strong> 4 bánh xe xoay 360 độ êm ái có khóa bánh chống trượt</li><li><strong>Thông số:</strong> 35 x 45 x 77 cm</li><li><strong>Xuất xứ:</strong> IKEA Thụy Điển</li></ul>', 850000, 1150000, 26, 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=800', 'Thụy Điển', 'Bảo hành chính hãng 12-24 tháng', 4.6, 274, 394, 'ACTIVE', 0, '2026-08-16T04:56:16.312Z', '2026-08-16T04:56:16.312Z') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, image_url = EXCLUDED.image_url, status = 'ACTIVE';
